fn DL_DL_000(x: f64, z: f64, NF: f64) -> f64 {
    let res: f64 = 9. / 2. * pow(NQCD, -1) + (- 9. / 2. * NQCD) + (- 1. / 6. * pow(pi, 2) * pow(NQCD, -1)) + 1. / 6. * pow(pi, 2) * NQCD;
    return res;
}

fn DL_DL_100(x: f64, z: f64, NF: f64) -> f64 {
    let res: f64 = 3.0 * lmur * pow(NQCD, -1) + (- 3.0 * lmur * NQCD);
    return res;
}

